  set('surfaceDescription',t(`surface.${context.surface}Description`));
  $('surfaceAdminBadge').hidden=context.surface!=='admin';
  set('surfaceAdminBadge',t('surface.adminBadge'));
  const control=$('surfaceControl');
  if(!context.canSwitchSurface){control.hidden=true;return;}
  control.hidden=false;
  $('surfaceSwitcher').innerHTML=['workspace','admin'].map(surface=>`<button class="surface-button btn ${surface===context.surface?'active':''}" type="button" data-surface="${surface}" data-short="${surface==='admin'?'A':'W'}" aria-pressed="${surface===context.surface}">${esc(t(`surface.${surface}`))}</button>`).join('');
