function renderAdminOverview(){
  if(context.surface!=='admin'||context.page!=='admin-overview')return;
  const people=queryPeople({page:1,pageSize:10}),audit=queryAudit({page:1,pageSize:10});
  const runtime=context.syntheticRuntimeWarning;
  const entries=[
    {key:'resources',icon:'R',value:context.catalog.filter(resource=>resource.enabled).length,page:'resource-settings'},
    {key:'people',icon:'P',value:people.total,page:'people-overview'},
    {key:'audit',icon:'A',value:audit.total,page:'audit'},
    {key:'runtime',icon:'!',value:runtime?t(`runtime.authorizationStatus.${runtime.authorizationStatus}`):t('adminOverview.synthetic'),page:''}
  ];
  $('adminOverviewGrid').innerHTML=entries.map(item=>`<div class="col-12 col-md-6 col-xl-3"><article class="fin-admin-entry-card card h-100 d-flex flex-column"><div class="admin-entry-icon">${esc(item.icon)}</div><h2>${esc(t(`adminOverview.${item.key}Title`))}</h2><p>${esc(t(`adminOverview.${item.key}Description`))}</p><div class="admin-entry-meta"><strong>${esc(item.value)}</strong>${item.page?`<button class="admin-entry-button btn btn-sm" type="button" data-admin-page="${item.page}">${esc(t('adminOverview.open'))}</button>`:`<span class="badge">${esc(t('adminOverview.synthetic'))}</span>`}</div></article></div>`).join('');
  $('adminOverviewGrid').querySelectorAll('[data-admin-page]').forEach(button=>button.onclick=()=>goto(button.dataset.adminPage));
}
function resMarkup(r,mobile=false){ const name=rName(r),cat=rCategory(r),desc=rDesc(r),launch=`<button class="launch-button btn" data-resource="${esc(name)}">${esc(t('catalog.launch'))}</button>`; if(mobile)return `<article class="mobile-resource-card card"><div class="system-cell"><span class="system-icon">${esc(r.icon)}</span>${esc(name)}</div><p>${esc(desc)}</p><div class="mobile-resource-meta"><span>${esc(cat)}</span><span>${esc(roleLabel(context.effectiveRole))}</span></div>${launch}</article>`; return `<tr><td><div class="system-cell"><span class="system-icon">${esc(r.icon)}</span>${esc(name)}</div></td><td>${esc(cat)}</td><td class="resource-description">${esc(desc)}</td><td><span class="current-role-pill">${esc(roleLabel(context.effectiveRole))}</span></td><td class="action-cell">${launch}</td></tr>`; }
